'use strict'

/**
 * cdpc cluster launcher —— cdpc 的基础能力之一，随库发布。
 *
 * 设计前提：**cdpc 自身不做 cluster 管理**。
 * 一个 cluster 服务在 cdpc 眼里仍然只是"一个子进程"（就是本进程），
 * N 个 worker 由本进程负责 fork、补员与收尾。这样 cdpc 的状态机不必承担
 * M 个服务 × N 个 worker 的组合复杂度，多个服务同时开 cluster 也互不影响。
 *
 * 用法（由 cdpc 的 checkConfig 自动生成，一般不需要手工调用）：
 *   node launcher.js --workers N [--restart-window ms] [--restart-max n]
 *                    -- <目标js> [node启动参数...] [应用参数...]
 *
 * 为什么 worker 能共享端口：node 的 cluster 模块由 primary 持有监听句柄并分发，
 * 目标应用不需要改一行代码。worker 用的 node 二进制**必然**是本进程的 execPath
 * （cluster.settings 没有 execPath 可配），所以本进程必须由用户配置里那个 node 启动。
 */

const cluster = require('cluster')
const os = require('os')
const path = require('path')

const TAG = '[cdpc-launcher]'

function log(msg) {
  console.log(`${TAG} ${msg}`)
}

function errlog(msg) {
  console.error(`${TAG} ${msg}`)
}

/** 取值型的 node 启动参数：值是下一个 token，不能被误当成入口脚本 */
const VALUE_EXEC_FLAGS = ['-r', '--require', '-e', '--eval', '--import', '--loader', '--experimental-loader']

/**
 * 解析命令行：--workers N ... -- <目标与参数>
 * 目标段里入口脚本之前的 flag 属于 node 启动参数（execArgv），
 * 之后的才是应用参数。混在一起传会让 worker 把 --max-old-space-size 当业务参数。
 */
function parseArgv(argv) {
  let opt = {
    workers: 1,
    restartWindow: 60000,
    restartMax: 0,
    stopTimeout: 3000,
    execArgv: [],
    exec: '',
    args: []
  }

  let i = 0
  let rest = []

  while (i < argv.length) {
    let a = argv[i]

    if (a === '--') {
      rest = argv.slice(i + 1)
      break
    }

    let next = argv[i + 1]

    switch (a) {
      case '--workers':
        opt.workers = parseInt(next, 10)
        i += 2
        break

      case '--restart-window':
        opt.restartWindow = parseInt(next, 10)
        i += 2
        break

      case '--restart-max':
        opt.restartMax = parseInt(next, 10)
        i += 2
        break

      case '--stop-timeout':
        opt.stopTimeout = parseInt(next, 10)
        i += 2
        break

      default:
        i += 1
    }
  }

  // 目标段：入口脚本之前的 flag → execArgv
  let k = 0
  while (k < rest.length) {
    let t = rest[k]

    if (t[0] !== '-') break

    opt.execArgv.push(t)

    if (VALUE_EXEC_FLAGS.indexOf(t) >= 0 && rest[k + 1] !== undefined) {
      opt.execArgv.push(rest[k + 1])
      k += 2
      continue
    }

    k += 1
  }

  opt.exec = rest[k] || ''
  opt.args = rest.slice(k + 1)

  if (!isFinite(opt.workers) || opt.workers <= 0) opt.workers = os.cpus().length
  if (!isFinite(opt.restartWindow) || opt.restartWindow < 1000) opt.restartWindow = 60000
  if (!isFinite(opt.stopTimeout) || opt.stopTimeout < 100) opt.stopTimeout = 3000
  // 熔断阈值默认按 worker 数放大，避免正常滚动重启被误熔断
  if (!isFinite(opt.restartMax) || opt.restartMax <= 0) opt.restartMax = Math.max(10, opt.workers * 5)

  return opt
}

const opt = parseArgv(process.argv.slice(2))

if (!opt.exec) {
  errlog('缺少入口脚本：用法 launcher.js --workers N -- <目标js> [参数...]')
  process.exit(1)
}

cluster.setupPrimary({
  exec: path.resolve(opt.exec),
  args: opt.args,
  execArgv: opt.execArgv,
  // silent：worker 输出走管道，由本进程加 [wN] 前缀后转发；
  // 否则 N 个 worker 的输出混在一起，排查时无法定位到具体实例。
  silent: true
})

// worker 槽位：pid → workerId，补员后仍保持同一个序号
let slots = new Map()
// 滑动窗口内的补员时间戳，用于熔断
let restarts = []
let shuttingDown = false
// 期望存活的 worker 序号集合（0..N-1）；reconcile 以它为准
let wantIds = new Set()

/**
 * 出向缓冲上限：worker 输出经本进程转发，而本进程的 stdout 往往是一根管道。
 * 若上游（cdpcd 或调用方）不读这根管道，Node 会把写入无界缓冲在内存里——
 * 高日志量的 worker 能把 launcher 撑到 OOM，进而带走整组服务。
 * 超过上限就丢弃输出并计数，日志可以丢，进程管理不能倒。
 */
const OUT_BUFFER_LIMIT = 4 * 1024 * 1024
let droppedLines = 0
let dropWarned = 0

function safeWrite(out, text) {
  if (out.writableLength > OUT_BUFFER_LIMIT) {
    droppedLines++

    // 告警本身也要节流，否则丢弃时反过来刷日志
    let now = Date.now()
    if (now - dropWarned > 10000) {
      dropWarned = now
      try {
        out.write(`${TAG} 出向缓冲超过 ${OUT_BUFFER_LIMIT} 字节（上游未读取），`
          + `已丢弃 ${droppedLines} 行 worker 输出\n`)
      } catch (err) {}
    }
    return
  }

  try { out.write(text) } catch (err) {}
}

function attachOutput(worker, id) {
  let pipe = (stream, out) => {
    if (!stream) return

    let buf = ''

    stream.setEncoding('utf8')
    stream.on('data', chunk => {
      buf += chunk

      let idx = buf.indexOf('\n')
      while (idx >= 0) {
        safeWrite(out, `[w${id}] ${buf.substring(0, idx)}\n`)
        buf = buf.substring(idx + 1)
        idx = buf.indexOf('\n')
      }

      // 单行过长同样不能无界积累（应用可能一直不输出换行）
      if (buf.length > 64 * 1024) {
        safeWrite(out, `[w${id}] ${buf}\n`)
        buf = ''
      }
    })

    stream.on('end', () => {
      if (buf) safeWrite(out, `[w${id}] ${buf}\n`)
    })

    stream.on('error', () => {})
  }

  pipe(worker.process.stdout, process.stdout)
  pipe(worker.process.stderr, process.stderr)
}

function forkWorker(id) {
  try {
    let worker = cluster.fork({CDPC_WORKER_ID: String(id)})

    slots.set(worker.process.pid, id)
    attachOutput(worker, id)

    return worker
  } catch (err) {
    // fork 失败（内存不足、fd 耗尽等）不会产生 exit 事件，
    // 只靠 exit 补员会导致该槽位永久空缺，由 reconcile 兜底
    errlog(`fork w${id} 失败: ${err.message}，将由 reconcile 重试`)
    return null
  }
}

/** 当前存活的 workerId 集合 */
function aliveIds() {
  let ids = new Set()

  for (let k in cluster.workers) {
    let w = cluster.workers[k]
    let id = slots.get(w.process.pid)
    if (id !== undefined) ids.add(id)
  }

  return ids
}

/**
 * 维持平衡：以 wantIds 为准补齐缺失的槽位。
 * exit 事件是主路径，这里兜住两种它覆盖不到的情况：
 *   1. fork 本身抛错（没有 exit 事件可依赖）
 *   2. 任何原因导致的计数漂移
 */
function reconcile() {
  if (shuttingDown) return

  let alive = aliveIds()
  let missing = []

  for (let id of wantIds) {
    if (!alive.has(id)) missing.push(id)
  }

  if (missing.length === 0) return

  if (overRestartLimit(missing.length)) {
    errlog(`补员过于频繁（${opt.restartWindow}ms 内超过 ${opt.restartMax} 次），停止补员并退出`)
    shuttingDown = true
    stopAll('SIGKILL')
    process.exit(1)
    return
  }

  errlog(`reconcile：缺 ${missing.length} 个 worker (${missing.map(x => 'w' + x).join(',')})，补齐`)

  for (let id of missing) forkWorker(id)
}

/** 熔断：worker 起来就崩时，不能无限 fork 刷进程 */
function overRestartLimit(count = 1) {
  let now = Date.now()

  restarts = restarts.filter(t => now - t < opt.restartWindow)

  for (let i = 0; i < count; i++) restarts.push(now)

  return restarts.length > opt.restartMax
}

cluster.on('exit', (worker, code, sig) => {
  let id = slots.get(worker.process.pid)
  slots.delete(worker.process.pid)

  if (shuttingDown) {
    // 停机中：worker 全部退出后本进程才退出。
    // 顺序很重要——master 必须最后退，否则残余 worker 会变孤儿。
    if (Object.keys(cluster.workers).length === 0) {
      log('全部 worker 已退出，master 退出')
      process.exit(0)
    }
    return
  }

  if (id === undefined) return

  errlog(`worker ${worker.process.pid} (w${id}) 退出 code=${code} signal=${sig}，补充中`)

  if (overRestartLimit()) {
    errlog(`补员过于频繁（${opt.restartWindow}ms 内超过 ${opt.restartMax} 次），停止补员并退出`)
    shuttingDown = true
    stopAll('SIGKILL')
    process.exit(1)
    return
  }

  forkWorker(id)
})

cluster.on('error', err => {
  errlog(`cluster 错误: ${err.message}`)
})

function stopAll(sig) {
  for (let id in cluster.workers) {
    let w = cluster.workers[id]
    try { w.process.kill(sig) } catch (err) {}
  }
}

/**
 * 停机流程（顺序是关键）：
 *
 *   1. **先关补员**（shuttingDown = true）。cdpc 的 stop 会向整棵子树发 SIGTERM，
 *      worker 会先于 master 收到；本进程若不先关补员，就会在退出前因为收到
 *      worker 的 exit 事件而 fork 出替补，与停机过程打架并留下孤儿。
 *   2. 向所有 worker 发 SIGTERM，给它们优雅收尾的机会。
 *   3. 全部退出 → master 退出（在 exit 事件里判定）。
 *      **master 必须最后退**，否则残余 worker 会被 PID 1 收养成孤儿。
 *   4. 超时仍有存活 → SIGKILL 强制终止（应对忽略 SIGTERM 的 worker），
 *      再留一小段确认窗口后退出。
 *
 * 三层超时的关系（必须由外到内递减，否则内层没机会执行）：
 *   cdpc 的 stop 兜底 SIGKILL  >  本进程的 stopTimeout  >  worker 自己的收尾时间
 */
function shutdown(sig) {
  if (shuttingDown) return

  shuttingDown = true

  let n = Object.keys(cluster.workers).length
  log(`收到 ${sig}，停止补员并通知 ${n} 个 worker 退出（强制终止阈值 ${opt.stopTimeout}ms）`)

  if (n === 0) {
    process.exit(0)
    return
  }

  stopAll('SIGTERM')

  let killTimer = setTimeout(() => {
    let left = Object.keys(cluster.workers).length

    if (left === 0) {
      process.exit(0)
      return
    }

    // 强制终止：SIGTERM 被忽略的 worker 只能靠 SIGKILL
    let pids = []
    for (let k in cluster.workers) {
      let w = cluster.workers[k]
      pids.push(`${w.process.pid}(w${slots.get(w.process.pid)})`)
    }

    errlog(`${opt.stopTimeout}ms 内仍有 ${left} 个 worker 未退出 [${pids.join(' ')}]，SIGKILL 强制终止`)
    stopAll('SIGKILL')

    // SIGKILL 无法被捕获，但仍要等内核回收后再退，
    // 保证 master 是最后一个退出的（不留孤儿）
    let confirm = setTimeout(() => {
      let still = Object.keys(cluster.workers).length
      still > 0 && errlog(`SIGKILL 后仍有 ${still} 个 worker 记录未清理，直接退出`)
      process.exit(0)
    }, 500)

    confirm.unref && confirm.unref()
  }, opt.stopTimeout)

  killTimer.unref && killTimer.unref()
}

process.on('SIGTERM', () => shutdown('SIGTERM'))
process.on('SIGINT', () => shutdown('SIGINT'))
process.on('SIGHUP', () => {})

/**
 * 孤儿自检：父进程（cdpcd）被 SIGKILL 时它没机会通知任何人，
 * 本进程会被 PID 1 收养并继续持有 N 个 worker；等 cdpcd 重启又会起一份，
 * 于是出现重复服务与端口冲突。这里检测"父进程变成了 1"就自行收尾。
 *
 * 注意不能简单地判 ppid === 1：服务配了 detached 时启动瞬间 ppid 本来就是 1。
 * 所以记录启动时的 ppid，只有从非 1 变成 1 才是被收养。
 */
const bornPpid = process.ppid

if (bornPpid !== 1) {
  let orphanTimer = setInterval(() => {
    if (shuttingDown) return

    if (process.ppid === 1) {
      errlog(`父进程已消失（原 ppid=${bornPpid}），停止补员并带走 worker`)
      shutdown('ORPHAN')
    }
  }, 2000)

  orphanTimer.unref && orphanTimer.unref()
}

log(`启动 ${opt.workers} 个 worker：${opt.exec}`
  + (opt.execArgv.length ? ` execArgv=[${opt.execArgv.join(' ')}]` : '')
  + (opt.args.length ? ` args=[${opt.args.join(' ')}]` : ''))

for (let i = 0; i < opt.workers; i++) {
  wantIds.add(i)
  forkWorker(i)
}

// 维持平衡的兜底巡检（exit 事件是主路径，这里覆盖 fork 失败等情况）
let reconcileTimer = setInterval(reconcile, 3000)
reconcileTimer.unref && reconcileTimer.unref()
